export class Channelstack extends ClientBase {
  readonly #ctx: HandleContext;

  /** @internal Handles come from the SDK, never from `new`. */
  constructor(transport: Transport, stop: () => Promise<void>) {
    super(stop);
    this.#ctx = { transport, session: undefined };
  }

  /** Server health, version and loaded drivers. */
  async status(): Promise<Status> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/status`)) as Status;
    return data;
  }

  /** Open a session: a scope in the shared world that owns what it creates. */
  async openSession(options: { name?: string } = {}): Promise<Session> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions`, { body: { name: options.name } })) as SessionData;
    return new Session({ transport: ctx.transport, session: data.sessionId }, data);
  }

  /** Drop the whole world. Avoid in parallel suites. */
  async reset(): Promise<void> {
    const ctx = this.#ctx;
    await ctx.transport.request("POST", `/reset`);
  }

  /** Env vars for the agent: fake tokens, signing secrets and API URLs (what `channelstack env` prints). With `proxy`, the proxy and the CA instead of the API URLs. */
  async env(options: { proxy?: boolean } = {}): Promise<Env> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/env`, { query: { proxy: options.proxy } })) as Env;
    return data;
  }

  /** A new one-time link that opens the UI in a browser (what `channelstack ui` prints). Experimental. */
  async uiLoginLink(): Promise<UiLoginLink> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/ui/login-links`)) as UiLoginLink;
    return data;
  }
}

/** Wire data of a {@link Session}. */
export interface SessionData {
  sessionId: string;
  drivers: string[];
}

export class Session implements AsyncDisposable {
  readonly sessionId: string;
  readonly drivers: string[];
  readonly #ctx: HandleContext;

  /** @internal Handles come from the SDK, never from `new`. */
  constructor(ctx: HandleContext, data: SessionData) {
    this.#ctx = ctx;
    this.sessionId = data.sessionId;
    this.drivers = data.drivers;
  }

  /** Close a session and remove everything it created. */
  async close(): Promise<void> {
    const ctx = this.#ctx;
    await ctx.transport.request("DELETE", `/sessions/${segment(sessionOf(ctx))}`);
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await disposeQuietly(() => this.close());
  }

  /** The session's event log: actions, deliveries with every attempt, and the agent's API calls. */
  async events(options: { since?: string } = {}): Promise<EventPage> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/events`, { query: { since: options.since } })) as EventPage;
    return data;
  }

  /** Is the agent idle in this session, and for how long? Negative and exact-count matchers wait for this. */
  async quiet(): Promise<Quiet> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/quiet`)) as Quiet;
    return data;
  }

  /** The echo fixture: the agent's app and where it reaches the fake. Experimental. */
  async echo(): Promise<EchoFixture> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/echo`)) as EchoFixtureData;
    return new EchoFixture(ctx, data);
  }

  /** The Slack fixture: the agent's app, the workspace, and where the agent reaches the fake. Experimental. */
  async slack(): Promise<SlackFixture> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/slack`)) as SlackFixtureData;
    return new SlackFixture(ctx, data);
  }

  /** The GitHub fixture: the agent's App, the org, and where the agent reaches the fake. Experimental. */
  async github(): Promise<GitHubFixture> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/github`)) as GitHubFixtureData;
    return new GitHubFixture(ctx, data);
  }

  /** The Linear fixture: the agent's app, and where the agent reaches the fake. Experimental. */
  async linear(): Promise<LinearFixture> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/linear`)) as LinearFixtureData;
    return new LinearFixture(ctx, data);
  }

  /** The Notion fixture: the agent's integration, and where the agent reaches the fake. Experimental. */
  async notion(): Promise<NotionFixture> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/notion`)) as NotionFixtureData;
    return new NotionFixture(ctx, data);
  }

  /** The Resend fixture: the agent's team, and where the agent reaches the fake. Experimental. */
  async resend(): Promise<ResendFixture> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/resend`)) as ResendFixtureData;
    return new ResendFixture(ctx, data);
  }

  /** The Google fixture: the agent's mailbox, and where the agent reaches the fake. Experimental. */
  async google(): Promise<GoogleFixture> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/google`)) as GoogleFixtureData;
    return new GoogleFixture(ctx, data);
  }

  /** @internal Is the agent quiet in this handle's session? Matchers ask this. */
  [QUIET](): Promise<QuietState> {
    return quietOf(this.#ctx);
  }
}

