/** Wire data of a {@link SlackFixture}. */
export interface SlackFixtureData {
  app: SlackAppData;
  apiUrl: string;
  team: SlackTeam;
  socketConnections: number;
}

export class SlackFixture {
  readonly app: SlackApp;
  readonly apiUrl: string;
  readonly team: SlackTeam;
  readonly socketConnections: number;
  readonly #ctx: HandleContext;
  readonly #seen = new Map<string, number>();

  /** @internal Handles come from the SDK, never from `new`. */
  constructor(ctx: HandleContext, data: SlackFixtureData) {
    this.#ctx = ctx;
    this.app = new SlackApp(ctx, data.app);
    this.apiUrl = data.apiUrl;
    this.team = data.team;
    this.socketConnections = data.socketConnections;
  }

  /** Create a person in the workspace. Experimental. */
  async createUser(options: { name: string; id?: string; displayName?: string; realName?: string; email?: string; timezone?: string; admin?: boolean; owner?: boolean; guest?: boolean; bot?: boolean; token?: string; browser?: { storageState: string } }): Promise<SlackUser> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/slack/users`, { body: { name: options.name, id: options.id, displayName: options.displayName, realName: options.realName, email: options.email, timezone: options.timezone, admin: options.admin, owner: options.owner, guest: options.guest, bot: options.bot, token: options.token ?? credential("CHANNELSTACK_SLACK_USER_{name}_TOKEN", { name: options.name }), browser: options.browser } })) as SlackUserData;
    return new SlackUser(ctx, data);
  }

  /** The people this session created. Experimental. */
  async users(): Promise<SlackUsers> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/slack/users`)) as SlackUsersWire;
    return decodeSlackUsers(ctx, data);
  }

  /** The session's conversations, the one with the newest message last. Experimental. */
  async conversations(): Promise<SlackConversations> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/slack/conversations`)) as SlackConversationsWire;
    return decodeSlackConversations(ctx, data);
  }

  /** Create a channel. Only the listed participants are members; include the app for it to receive events. Experimental. */
  async createChannel(options: { name?: string; private?: boolean; participants?: Array<SlackUser | SlackApp>; topic?: string; purpose?: string; shared?: boolean } = {}): Promise<SlackConversation> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/slack/channels`, { body: { name: options.name, private: options.private, participants: options.participants === undefined ? undefined : options.participants.map((item) => item.id), topic: options.topic, purpose: options.purpose, shared: options.shared } })) as SlackConversationData;
    return new SlackConversation(ctx, data);
  }

  /** Every event channelstack sent the agent for this session, with every attempt. Experimental. */
  async deliveries(): Promise<SlackDeliveries> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/slack/deliveries`)) as SlackDeliveriesWire;
    return decodeSlackDeliveries(ctx, data);
  }

  /** The Web API calls the agent made about this session's conversations, people and files. Calls about nothing a session owns (auth.test, users.list) are in no session. Experimental. */
  async calls(options: { operation?: string; error?: true | string } = {}): Promise<SlackApiCalls> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/slack/calls`, { query: { operation: options.operation, error: options.error } })) as SlackApiCalls;
    return data;
  }

  /** The workspace uninstalls the app. Undone when this session closes; run such tests on their own. Experimental. */
  async uninstallApp(): Promise<SlackUninstallDeliveries> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/slack/uninstall`)) as SlackUninstallDeliveriesWire;
    return decodeSlackUninstallDeliveries(ctx, data);
  }

  /** Inject a fault: into the agent's Web API calls (removed when this session closes), or drop its Socket Mode connection once. Experimental. */
  async fault(options: { type: "rate_limit" | "latency" | "error" | "drop_socket"; operation?: string; retryAfter?: Duration; delay?: Duration; after?: Duration; error?: string; times?: number }): Promise<SlackFault> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/slack/faults`, { body: { type: options.type, operation: options.operation, retryAfter: options.retryAfter === undefined ? undefined : parseDuration(options.retryAfter), delay: options.delay === undefined ? undefined : parseDuration(options.delay), after: options.after === undefined ? undefined : parseDuration(options.after), error: options.error, times: options.times } })) as SlackFaultData;
    return new SlackFault(ctx, data);
  }

  /** Wait for the next new API call from the agent, after the last one this handle saw. */
  async waitForCall(filter: { operation?: string; error?: true | string }, options: WaitOptions = {}): Promise<SlackApiCall> {
    return waitForNext(this.#seen, `waitForCall:${JSON.stringify(filter)}`, () => this.calls(filter), () => true, "an API call from the agent", options);
  }

  /** @internal Is the agent quiet in this handle's session? Matchers ask this. */
  [QUIET](): Promise<QuietState> {
    return quietOf(this.#ctx);
  }
}

