/** Wire data of a {@link SlackDelivery}. */
export interface SlackDeliveryData {
  id: string;
  channel: "slack";
  type: string;
  eventType?: string;
  eventId?: string;
  payload?: unknown;
  attempts: DeliveryAttempt[];
  status: "pending" | "acknowledged" | "failed" | "timed_out" | "unreachable";
}

export class SlackDelivery {
  readonly id: string;
  readonly channel: "slack";
  readonly type: string;
  readonly eventType: string | undefined;
  readonly eventId: string | undefined;
  readonly payload: unknown | undefined;
  readonly attempts: DeliveryAttempt[];
  readonly status: "pending" | "acknowledged" | "failed" | "timed_out" | "unreachable";
  readonly #ctx: HandleContext;

  /** @internal Handles come from the SDK, never from `new`. */
  constructor(ctx: HandleContext, data: SlackDeliveryData) {
    this.#ctx = ctx;
    this.id = data.id;
    this.channel = data.channel;
    this.type = data.type;
    this.eventType = data.eventType;
    this.eventId = data.eventId;
    this.payload = data.payload;
    this.attempts = data.attempts;
    this.status = data.status;
  }

  /** Re-read a delivery: its attempts and status. Experimental. */
  async refresh(): Promise<SlackDelivery> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/slack/deliveries/${segment(this.id)}`)) as SlackDeliveryData;
    return new SlackDelivery(ctx, data);
  }

  /** Send the delivery again, unchanged or forged: a wrong signature, or a timestamp outside the replay window. Experimental. */
  async resend(options: { badSignature?: boolean; stale?: boolean; headers?: Record<string, string> } = {}): Promise<DeliveryAttempt> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/slack/deliveries/${segment(this.id)}/resend`, { body: { badSignature: options.badSignature, stale: options.stale, headers: options.headers } })) as DeliveryAttempt;
    return data;
  }

  /** Retry the way Slack does: the same payload, with X-Slack-Retry-Num and X-Slack-Retry-Reason. Experimental. */
  async retry(options: { after?: Duration; reason?: "http_timeout" | "http_error" | "too_many_redirects" } = {}): Promise<DeliveryAttempt> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/slack/deliveries/${segment(this.id)}/retry`, { body: { after: options.after === undefined ? undefined : parseDuration(options.after), reason: options.reason } })) as DeliveryAttempt;
    return data;
  }

  /** Wait for the delivery to settle, and resolve with the value as it is then. */
  async settled(options: WaitOptions = {}): Promise<SlackDelivery> {
    return waitFor("the delivery to settle", async () => {
      const value = await this.refresh();
      return value.status === "pending" ? undefined : value;
    }, options);
  }

  /** @internal Is the agent quiet in this handle's session? Matchers ask this. */
  [QUIET](): Promise<QuietState> {
    return quietOf(this.#ctx);
  }
}

