  async redeliver(): Promise<DeliveryAttempt> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/notion/deliveries/${segment(this.id)}/redeliver`)) as DeliveryAttempt;
    return data;
  }

