/** Wire data of a {@link GoogleDelivery}. */
export interface GoogleDeliveryData {
  id: string;
  channel: "google";
  type: string;
  emailAddress: string;
  historyId: string;
  payload?: unknown;
  attempts: DeliveryAttempt[];
  status: "pending" | "acknowledged" | "failed" | "timed_out" | "unreachable";
}

export class GoogleDelivery {
  readonly id: string;
  readonly channel: "google";
  readonly type: string;
  readonly emailAddress: string;
  readonly historyId: string;
  readonly payload: unknown | undefined;
  readonly attempts: DeliveryAttempt[];
  readonly status: "pending" | "acknowledged" | "failed" | "timed_out" | "unreachable";
  readonly #ctx: HandleContext;

  /** @internal Handles come from the SDK, never from `new`. */
  constructor(ctx: HandleContext, data: GoogleDeliveryData) {
    this.#ctx = ctx;
    this.id = data.id;
    this.channel = data.channel;
    this.type = data.type;
    this.emailAddress = data.emailAddress;
    this.historyId = data.historyId;
    this.payload = data.payload;
    this.attempts = data.attempts;
    this.status = data.status;
  }

  /** Re-read a delivery: its attempts and status. Experimental. */
  async refresh(): Promise<GoogleDelivery> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/google/deliveries/${segment(this.id)}`)) as GoogleDeliveryData;
    return new GoogleDelivery(ctx, data);
  }

  /** Push the same message again, as Pub/Sub does when a push isn't acknowledged: the same message id. Experimental. */
  async redeliver(): Promise<DeliveryAttempt> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/google/deliveries/${segment(this.id)}/redeliver`)) as DeliveryAttempt;
    return data;
  }

  /** Push it again, forged: with a token signed by another key, one that has expired, or one for another audience than the push endpoint. Experimental. */
  async resend(options: { badSignature?: boolean; stale?: boolean; wrongAudience?: boolean } = {}): Promise<DeliveryAttempt> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("POST", `/sessions/${segment(sessionOf(ctx))}/google/deliveries/${segment(this.id)}/resend`, { body: { badSignature: options.badSignature, stale: options.stale, wrongAudience: options.wrongAudience } })) as DeliveryAttempt;
    return data;
  }

  /** Wait for the delivery to settle, and resolve with the value as it is then. */
  async settled(options: WaitOptions = {}): Promise<GoogleDelivery> {
    return waitFor("the delivery to settle", async () => {
      const value = await this.refresh();
      return value.status === "pending" ? undefined : value;
    }, options);
  }

  /** @internal Is the agent quiet in this handle's session? Matchers ask this. */
  [QUIET](): Promise<QuietState> {
    return quietOf(this.#ctx);
  }
}

/** Wire data of a {@link GitHubPullRequest}. */
export interface GitHubPullRequestData extends GitHubIssueData {
  head: string;
  base: string;
}

export class GitHubPullRequest extends GitHubIssue {
  readonly head: string;
  readonly base: string;
  readonly #ctx: HandleContext;

  /** @internal Handles come from the SDK, never from `new`. */
  constructor(ctx: HandleContext, data: GitHubPullRequestData) {
    super(ctx, data);
    this.#ctx = ctx;
    this.head = data.head;
    this.base = data.base;
  }

  /** Read the pull request again. Experimental. */
  override async refresh(): Promise<GitHubPullRequest> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/github/repos/${segment(this.repoId)}/pulls/${segment(this.number)}`)) as GitHubPullRequestData;
    return new GitHubPullRequest(ctx, data);
  }

  /** The newest commit of the pull request's branch, once the agent is quiet. Experimental. */
  async headCommit(): Promise<GitHubCommit> {
    const ctx = this.#ctx;
    await untilQuiet(() => quietOf(ctx));
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/github/repos/${segment(this.repoId)}/pulls/${segment(this.number)}/head-commit`)) as GitHubCommitData;
    return new GitHubCommit(ctx, data);
  }

  /** The submitted reviews, oldest first. Experimental. */
  async reviews(): Promise<GitHubReviews> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/github/repos/${segment(this.repoId)}/pulls/${segment(this.number)}/reviews`)) as GitHubReviewsWire;
    return decodeGitHubReviews(ctx, data);
  }

  /** The comments on the diff, oldest first. Experimental. */
  async reviewComments(): Promise<GitHubReviewComments> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/github/repos/${segment(this.repoId)}/pulls/${segment(this.number)}/review-comments`)) as GitHubReviewCommentsWire;
    return decodeGitHubReviewComments(ctx, data);
  }

  /** The check runs on the pull request's newest commit: the newest of each name. Experimental. */
  async checkRuns(): Promise<GitHubPullCheckRuns> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/github/repos/${segment(this.repoId)}/pulls/${segment(this.number)}/check-runs`)) as GitHubPullCheckRunsWire;
    return decodeGitHubPullCheckRuns(ctx, data);
  }

  /** Has the pull request been merged?. Experimental. */
  async merged(): Promise<boolean> {
    const ctx = this.#ctx;
    const data = (await ctx.transport.request("GET", `/sessions/${segment(sessionOf(ctx))}/github/repos/${segment(this.repoId)}/pulls/${segment(this.number)}/merged`)) as boolean;
    return data;
  }
}

/** Attach to a running channelstack server, or start one, and return the client. */
export function connect(options: LaunchOptions = {}): Promise<Channelstack> {
  return connectWith(
    (transport, stop) => new Channelstack(transport, stop),
    { basePath: "/_channelstack", errors: ERRORS, version: VERSION },
    options,
  );
}
